scripts.王佐对话.txt:
//朱仙镇客栈中，王佐提示张琳心的脚本文件


	If($WangzuoMoney == 1)@WangzuoMoney;
	
	Say("王佐：张姑娘此行艰难，岳元帅特让在下给张姑娘备了些银两，以备不时之需。",63);
	Say("张琳心：多谢王将军！",21);
	AddMoney(1000);
	DisplayMessage("得到一千两银子");
	Assign(($WangzuoMoney,1);
	Return;

@WangzuoMoney:
	Say("王佐：双头人参生长在长白山千年朽木形成的洞窟里，常人极难发现……天山上住着一位性情古怪的旷世高人，名唤雪莲姥姥，专门守护天山雪莲。张姑娘可以选择去一个地方，另一个地方岳元帅会派两位得力手下去。",63);
	Return;

scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 420) @Event420;
	If ($Event == 430) @Event430;	
	If ($Event == 440) @Event440;
	If ($Event == 530) @Event530;
	If ($Event >= 695) @Event695;

	Return;
	
@Event420:	
	Say("张琳心：我们赶快去宋军大营吧。", 21);
	Return;
	
@Event430:
	Say("张琳心：独孤哥哥，我渴了，我们去茶馆喝茶吧。", 21);
	Say("独孤剑：好。", 2);
	Return;		

@Event440:
	Say("独孤剑：琳儿，休息得好吗？", 1);
	Say("张琳心：嗯，还不错！独孤哥哥，我们现在就去军营吧。", 21);
	SetNpcKind("张琳心", 3);
	SetMapTrap(1, "trap01.txt");
	Assign($zhang, 1);
	Return;

@Event530:
	Say("张琳心：我陪你出去走走吧。", 21);
	Return;
	
@Event695:
	Say("张琳心：独孤哥哥，我们快去岳飞大营。",21);
	Return;

scripts.客栈掌柜对话.txt:
// 与客栈掌柜对话
	
	If ($Event == 430) @Event430;
	If ($Event == 440) @Event440;
	If ($Event == 530) @Event530;
	
	Say("客栈掌柜：客官，要住店吗？五两银子一间房。", 86);
	Return;

@Event430:
	Say("客栈掌柜：客官，要住店吗？五两银子一间房。", 86);
	Say("张琳心：独孤哥哥，我想先去茶馆喝点茶。", 21);
	Say("独孤剑：好吧。", 2);
	Return;
	
@Event440:
	Say("客栈掌柜：客官，昨晚休息得好吗？", 86);
	Say("独孤剑：还不错。", 2);
	Return;	
	
@Event530:
	If ($Talkzhanggui == 0) @Talkzhanggui0;
	If ($Talkzhanggui == 1) @Talkzhanggui1;
 @Talkzhanggui0:	
	Say("客栈掌柜：独孤少侠看起来气色好多了。", 86);
	Say("独孤剑：琳儿说，这些日子多亏了大伯的照顾，独孤剑感激不尽！", 2);
	Say("客栈掌柜：少侠不必客气。对了，王贤弟说他有些事情，在码头等候二位。", 86);
	Assign($Talkzhanggui, 1);
	Memo("掌柜告知王佐在码头等候两人。");
	Return;
 @Talkzhanggui1:
	Say("客栈掌柜：王贤弟好像有事找二位，他正在码头等候。", 86);
	Return;

traps.trap01.txt:
//切换到朱仙镇

	If ($Event == 440) @Event440;
	If ($Event == 530) @Event530;
	
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map071_朱仙镇.map");
	LoadNpc("map071.npc");
	LoadObj("map071.obj");
	SetPlayerPos(10, 24);
	SetPlayerDir(1);
